// FileHeaderReset restores FileHeader's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func FileHeaderReset(value *FileHeader) {
	value.Schema = 0
}

func FileHeaderMeasureBody(value *FileHeader, ids *TableIds) int64 {
	bytes := int64(1)
	if (value.Schema != 0) && (value.Schema < 0 || value.Schema > 100000) {
		return -1
	}
	if value.Schema != 0 {
		bytes += tableLebBytes(ids.refAtHit(52, 0x758d17ff764667b6)) + 1 + 4
	} // schema
	if ids.Overflow {
		return -1
	}
	return bytes
}

func FileHeaderMeasure(value *FileHeader) int64 {
	var ids TableIds
	body := FileHeaderMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func FileHeaderMeasureReason(value *FileHeader) (int64, error) {
	size := FileHeaderMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
func FileHeaderSaveBody(w *TableWriter, value *FileHeader) bool {
	{
		if value.Schema != 0 {
			if ref := w.Ids.refAtHit(52, 0x758d17ff764667b6); !w.headerPair(ref, 4) {
				w.headerRest(ref, 4)
			}
			if value.Schema < 0 || value.Schema > 100000 {
				return false
			}
			w.Put32(uint32(value.Schema))
		}
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}

func FileHeaderSave(value *FileHeader, buffer []byte) int64 {
	var ids TableIds
	w := TableWriter{Buffer: buffer, Ids: &ids}
	w.Put8(1)
	if !FileHeaderSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func FileHeaderLoadBody(r *TableReader, value *FileHeader) bool {
	FileHeaderReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		switch fieldID {
		case 0x758d17ff764667b6: // schema
			if kind != 4 {
				if tableKindWidens(kind, 4) {
					if !r.Has(tableKindBytes(kind)) {
						r.Report.Malformed = true
						return false
					}
					{
						v := r.Signed(kind)
						if v < 0 {
							v = 0
							r.Report.Clamped++
						} else if v > 100000 {
							v = 100000
							r.Report.Clamped++
						}
						value.Schema = int32(v)
					}
					r.Report.Widened++
					break
				}
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(4) {
				r.Report.Malformed = true
				return false
			}
			{
				v := int32(r.Get32())
				if v < 0 {
					v = 0
					r.Report.Clamped++
				} else if v > 100000 {
					v = 100000
					r.Report.Clamped++
				}
				value.Schema = int32(v)
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

