func CanonicalWordLoadBody(r *TableReader, value *CanonicalWord) bool {
	CanonicalWordReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		switch fieldID {
		case 0xef9c96d721673243: // kind
			if kind != 30 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				variantRef, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				if variantRef == 0 {
					value.Kind = ConfigKindNone
				} else {
					id, ok := r.Resolve(variantRef)
					if !ok {
						r.Report.Malformed = true
						return false
					}
					if !value.Kind.TableEnumValue(id) {
						r.Report.Unknown++
					}
				}
			}
		case 0x6ae07b83701d11a0: // field_type
			if kind != 30 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				variantRef, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				if variantRef == 0 {
					value.FieldType = FieldTypeNone
				} else {
					id, ok := r.Resolve(variantRef)
					if !ok {
						r.Report.Malformed = true
						return false
					}
					if !value.FieldType.TableEnumValue(id) {
						r.Report.Unknown++
					}
				}
			}
		case 0x08b05607b556600a: // op
			if kind != 30 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			{
				variantRef, ok := r.Leb()
				if !ok {
					r.Report.Malformed = true
					return false
				}
				if variantRef == 0 {
					value.Op = ChangeOpNone
				} else {
					id, ok := r.Resolve(variantRef)
					if !ok {
						r.Report.Malformed = true
						return false
					}
					if !value.Op.TableEnumValue(id) {
						r.Report.Unknown++
					}
				}
			}
		case 0xbe417b3c16299522: // singleton
			if kind != 1 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(1) {
				r.Report.Malformed = true
				return false
			}
			value.Singleton = r.Get8() != 0
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

// CanonicalWord also carries the FIXED form (form 3): CanonicalWordFixedLoad reads that one and
// names a form-1 file `previous_form`. This Load is the VARIABLE form's entry
// point and reads form 1, whether or not the table was DECLARED fixed
// (mas-bandwidth/schema docs/SPEC-TABLES.md §3.4, §15).
func CanonicalWordLoad(value *CanonicalWord, data []byte, report *TableReport) bool {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, verdict := tableOpen(data, report)
	report.Verdict = verdict
	report.Reason = ""
	if verdict == TableOpenRefused {
		report.Reason = "unsupported wire form"
		if len(data) > 0 && data[0] == 2 {
			report.Reason = "message form requires an announced vocabulary and a message reader"
		}
	}
	if verdict != TableOpenOk {
		CanonicalWordReset(value)
		if verdict == TableOpenDamaged {
			report.Malformed = true
		}
		return false
	}
	// The root read answers its own early end after the walk, not before it.
	// A body that returned at its zero reference left the cursor on the byte
	// after that reference. Every field leaves the cursor where skip would, so
	// r.Offset != len(r.Buffer) is the old EndsEarly on the true path.
	// Nothing is decoded on the damaged path: the value goes back to defaults
	// and the report goes back to what the caller handed in, so an early end
	// counts no unknown, no kind mismatch and no clamp — as when the framing
	// walk refused before the reader had seen one byte.
	before := *report
	if !CanonicalWordLoadBody(&r, value) {
		// The reading walk stops on rules the framing walk has no opinion about
		// — a reserved id in a file body is the one that matters — so a body
		// that stopped is still asked the framing question from the start of
		// the body, and a body whose framing ends early is damage whatever else
		// was wrong with it.
		probe := r
		probe.Offset = 0
		if probe.EndsEarly() {
			CanonicalWordReset(value)
			*report = before
			report.Malformed = true
			report.Verdict = TableOpenDamaged
			return false
		}
		report.Verdict = TableOpenBodyStopped
		return false
	}
	if r.Offset != int64(len(r.Buffer)) {
		CanonicalWordReset(value)
		*report = before
		report.Malformed = true
		report.Verdict = TableOpenDamaged
		return false
	}
	return true
}

// CanonicalWordReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, one typed reason.
func CanonicalWordReadStrict(wire []byte) (*CanonicalWord, error) {
	value := new(CanonicalWord)
	var report TableReport
	ok := CanonicalWordLoad(value, wire, &report)
	if err := report.Err(); err != nil || !ok {
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	return value, nil
}

