// MachineViewReset restores MachineView's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func MachineViewReset(value *MachineView) {
	clear(value.Name[:])
	value.NameLength = 0
	clear(value.User[:])
	value.UserLength = 0
	clear(value.Seat[:])
	value.SeatLength = 0
	value.Slots = 0
	value.Runners = 0
	clear(value.Roles[:])
	value.RolesLength = 0
	value.Tla = false
	value.Width = 0
	value.WidthPresent = false
}

func MachineViewMeasureBody(value *MachineView, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !MachineViewSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func MachineViewMeasure(value *MachineView) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !MachineViewSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func MachineViewMeasureReason(value *MachineView) (int64, error) {
	size := MachineViewMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
