// InventoryLoopReset restores InventoryLoop's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func InventoryLoopReset(value *InventoryLoop) {
	clear(value.Machine[:])
	value.MachineLength = 0
	clear(value.Name[:])
	value.NameLength = 0
	clear(value.Argv[:])
	value.ArgvLength = 0
	clear(value.Seat[:])
	value.SeatLength = 0
	for i := range value.Keys {
		EnvNameReset(&value.Keys[i])
	}
	value.KeysCount = 0
	value.Every = 0
	value.Keepalive = false
	value.Enabled = false
	clear(value.Log[:])
	value.LogLength = 0
}

func InventoryLoopMeasureBody(value *InventoryLoop, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !InventoryLoopSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func InventoryLoopMeasure(value *InventoryLoop) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !InventoryLoopSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func InventoryLoopMeasureReason(value *InventoryLoop) (int64, error) {
	size := InventoryLoopMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
