func HostViewMeasureBody(value *HostView, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !HostViewSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func HostViewMeasure(value *HostView) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !HostViewSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func HostViewMeasureReason(value *HostView) (int64, error) {
	size := HostViewMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
