// BenchBeatReset restores BenchBeat's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func BenchBeatReset(value *BenchBeat) {
	clear(value.Host[:])
	value.HostLength = 0
	value.AtMs = 0
	clear(value.Load1[:])
	value.Load1Length = 0
	clear(value.Ncpu[:])
	value.NcpuLength = 0
	clear(value.Cpu[:])
	value.CpuLength = 0
	clear(value.Os[:])
	value.OsLength = 0
	clear(value.Arch[:])
	value.ArchLength = 0
	clear(value.MemoryGb[:])
	value.MemoryGbLength = 0
}

func BenchBeatMeasureBody(value *BenchBeat, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !BenchBeatSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func BenchBeatMeasure(value *BenchBeat) int64 {
	var ids TableIds
	w := TableWriter{Measuring: true, Ids: &ids}
	w.Put8(1)
	if !BenchBeatSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func BenchBeatMeasureReason(value *BenchBeat) (int64, error) {
	size := BenchBeatMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
