const BenchBeatSaveRetainMessages = "BenchBeat: retention requires a region round trip through the VARIABLE form"
const BenchBeatLoadRetainMessages = "BenchBeat: retention requires a region round trip through the VARIABLE form"
const BenchBeatLoadRetain = "BenchBeat: retention requires a variable root and its region directory"
