// MemberBeatReset restores MemberBeat's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func MemberBeatReset(value *MemberBeat) {
	value.AtMs = 0
	value.Cores = 0
}

func MemberBeatMeasureBody(value *MemberBeat, ids *TableIds) int64 {
	bytes := int64(1)
	if (value.AtMs != 0) && (value.AtMs < 0 || value.AtMs > 253402300799999) {
		return -1
	}
	if value.AtMs != 0 {
		bytes += tableLebBytes(ids.refAtHit(30, 0x41fdbf81bf00fdc1)) + 1 + 8
	} // at_ms
	if (value.Cores != 0) && (value.Cores < 0 || value.Cores > 100000) {
		return -1
	}
	if value.Cores != 0 {
		bytes += tableLebBytes(ids.refAtHit(82, 0xce57648e554861b7)) + 1 + 4
	} // cores
	if ids.Overflow {
		return -1
	}
	return bytes
}

func MemberBeatMeasure(value *MemberBeat) int64 {
	var ids TableIds
	body := MemberBeatMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func MemberBeatMeasureReason(value *MemberBeat) (int64, error) {
	size := MemberBeatMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
func MemberBeatSaveBody(w *TableWriter, value *MemberBeat) bool {
	{
		if value.AtMs != 0 {
			if ref := w.Ids.refAtHit(30, 0x41fdbf81bf00fdc1); !w.headerPair(ref, 5) {
				w.headerRest(ref, 5)
			}
			if value.AtMs < 0 || value.AtMs > 253402300799999 {
				return false
			}
			w.Put64(uint64(value.AtMs))
		}
	}
	{
		if value.Cores != 0 {
			if ref := w.Ids.refAtHit(82, 0xce57648e554861b7); !w.headerPair(ref, 4) {
				w.headerRest(ref, 4)
			}
			if value.Cores < 0 || value.Cores > 100000 {
				return false
			}
			w.Put32(uint32(value.Cores))
		}
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}

func MemberBeatSave(value *MemberBeat, buffer []byte) int64 {
	var ids TableIds
	w := TableWriter{Buffer: buffer, Ids: &ids}
	w.Put8(1)
	if !MemberBeatSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

